buggy.nan_arg_ops_direct_inputs:
// Rust probe for NaN semantics in burn tensor reductions.
// Harness provides entrypoint `fn body()`.
use burn::tensor::{Tensor, backend::Backend};
use burn::tensor::ops::*;
use burn::backend::ndarray::NdArray;
use burn::tensor::TensorData;

type B = NdArray<f32>;

fn isnan(x: f32) -> bool { x.is_nan() }

fn record_all_nan_case() {
    let t: Tensor<B, 2> = Tensor::from([[f32::NAN, f32::NAN, 3.0f32]]);
    let argmax1 = t.clone().argmax(1);
    let argmin1 = t.clone().argmin(1);

    let t_all_nan: Tensor<B, 2> = Tensor::from([[f32::NAN, f32::NAN, f32::NAN]]);
    let argmax1_all_nan = t_all_nan.clone().argmax(1);

    // max_dim_with_indices(1)
    let (values, indices) = t.max_dim_with_indices(1);

    // Pull to host.
    let a1: Vec<i64> = argmax1.into_data().into_iter().collect();
    let am1: Vec<i64> = argmin1.into_data().into_iter().collect();
    let a1an: Vec<i64> = argmax1_all_nan.into_data().into_iter().collect();
    let idx: Vec<i64> = indices.into_data().into_iter().collect();
    let vals: Vec<f32> = values.into_data().into_iter().collect();

    probe_scalar("argmax1([[nan,nan,3]]))", a1[0] as f64);
    probe_scalar("argmin1([[nan,nan,3]]))", am1[0] as f64);
    probe_scalar("argmax1([[nan,nan,nan]]))", a1an[0] as f64);
    probe_scalar("max_dim_with_indices1(values_is_nan)", (isnan(vals[0]) as u8) as f64);
    probe_scalar("max_dim_with_indices1(indices)", idx[0] as f64);
}

fn record_non_last_dim_case() {
    // argmax(0) for shape (2,3): we only need NaN placement that matches report’s special case.
    let t: Tensor<B, 2> = Tensor::from([
        [f32::NAN, 1.0f32, 2.0f32],
        [f32::NAN, 3.0f32, 4.0f32],
    ]);
    let argmax0 = t.argamax(0);
    let out: Vec<i64> = argmax0.into_data().into_iter().collect();
    // Record all indices (3 columns).
    for (i,v) in out.iter().enumerate() {
        probe_scalar(&format!("argmax0(col{})", i), *v as f64);
    }
}

fn body() {
    record_all_nan_case();
    record_non_last_dim_case();
}
